def solve_math_problem(n: int) -> int:
    """
    Calculates the number of sequences {a_i} of length n such that
    a_1 = 1, a_n = 1, and a_{i+1}/a_i in {2, 1, -1/2}.

    Let a_i = 2^{k_i}. The condition a_{i+1}/a_i in {2, 1, -1/2}
    implies k_{i+1} - k_i in {1, 0, -1}.
    Since a_1 = 2^0 = 1 and a_n = 2^0 = 1, we have k_1 = 0 and k_n = 0.
    The sequence k_i represents a path of length n-1 starting at 0, 
    ending at 0, with steps in {1, 0, -1}.

    This is equivalent to the number of paths of length n-1 from 0 to 0
    using steps {1, 0, -1}, which is the coefficient of x^0 in (x + 1 + 1/x)^{n-1}.
    This is the (n-1)-th central trinomial coefficient.
    """
    if n < 1:
        return 0
    if n == 1:
        return 1

    steps = n - 1
    # dp[i][j] = number of paths of length i ending at value j
    # Since j can range from -steps to steps, we offset by steps.
    dp: Dict[int, int] = {0: 1}

    for _ in range(steps):
        new_dp: Dict[int, int] = {}
        for val, count in dp.items():
            for step in [-1, 0, 1]:
                new_val = val + step
                new_dp[new_val] = new_dp.get(new_val, 0) + count
        dp = new_dp

    return dp.get(0, 0)

