        if state in memo:
            return memo[state]

        res = 0
        limit = int(s_num[idx]) if not is_less else 9
        for digit in range(limit + 1):
            res += dp(idx + 1, current_sum - digit, is_less or (digit < limit), is_started or (digit > 0))

